-- Superior ProConnect 2.0 — additive application storage migration
-- Run ONLY against Cloudflare D1 superior-proconnect-data.
-- This stores structured records and document metadata, not photo/PDF file bytes.
CREATE TABLE IF NOT EXISTS spc2_subscribers (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,display_name TEXT,role TEXT NOT NULL CHECK(role IN ('customer','professional','owner')),industry TEXT CHECK(industry IN ('construction','automotive') OR industry IS NULL),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS spc2_payment_events (id TEXT PRIMARY KEY,paypal_event_id TEXT UNIQUE,paypal_transaction_id TEXT,subscriber_id TEXT,kind TEXT NOT NULL CHECK(kind IN ('estimate','membership','refund','other')),industry TEXT,amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),currency TEXT NOT NULL DEFAULT 'USD',status TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0 CHECK(verified IN (0,1)),occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,raw_event_sha256 TEXT,FOREIGN KEY(subscriber_id) REFERENCES spc2_subscribers(id));
CREATE TABLE IF NOT EXISTS spc2_subscription_records (id TEXT PRIMARY KEY,subscriber_id TEXT NOT NULL,industry TEXT NOT NULL CHECK(industry IN ('construction','automotive')),tier TEXT NOT NULL CHECK(tier IN ('essential','professional','elite')),paypal_subscription_id TEXT UNIQUE,paypal_plan_id TEXT,monthly_amount_cents INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',verified INTEGER NOT NULL DEFAULT 0 CHECK(verified IN (0,1)),started_at TEXT,ends_at TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(subscriber_id) REFERENCES spc2_subscribers(id));
CREATE TABLE IF NOT EXISTS spc2_estimate_records (id TEXT PRIMARY KEY,job_id TEXT,customer_id TEXT,professional_id TEXT,industry TEXT NOT NULL CHECK(industry IN ('construction','automotive')),description TEXT,amount_cents INTEGER,estimate_status TEXT NOT NULL DEFAULT 'draft',payment_event_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES spc2_subscribers(id),FOREIGN KEY(professional_id) REFERENCES spc2_subscribers(id),FOREIGN KEY(payment_event_id) REFERENCES spc2_payment_events(id));
CREATE TABLE IF NOT EXISTS spc2_document_metadata (id TEXT PRIMARY KEY,owner_id TEXT,job_id TEXT,estimate_id TEXT,storage_key TEXT NOT NULL UNIQUE,content_type TEXT NOT NULL,size_bytes INTEGER NOT NULL CHECK(size_bytes>=0),sha256 TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES spc2_subscribers(id),FOREIGN KEY(estimate_id) REFERENCES spc2_estimate_records(id));
CREATE INDEX IF NOT EXISTS spc2_payment_subscriber_idx ON spc2_payment_events(subscriber_id,occurred_at);
CREATE INDEX IF NOT EXISTS spc2_estimate_customer_idx ON spc2_estimate_records(customer_id,created_at);
CREATE INDEX IF NOT EXISTS spc2_subscription_subscriber_idx ON spc2_subscription_records(subscriber_id,status);
CREATE INDEX IF NOT EXISTS spc2_documents_owner_idx ON spc2_document_metadata(owner_id,created_at);
